29	 * functionality and a logger instance for all subclasses.
30	 *
31	 * @author Nils Bühner
32	 */
33	@Repository("genericDao")
34	public class GenericHibernateDao<E extends PersistentObject, ID extends Serializable> {
35	
36	    /**
37	     * The LOGGER instance (that will be available in all subclasses)
38	     */
39	    protected static final Logger logger = getLogger(GenericHibernateDao.class);
