93	    /**
94	     * Returns a list of entity objects that have field named
95	     * <code>fieldName</code>, which has an object <code>fieldEntity</code>
96	     * as value.
97	     *
98	     * @param fieldName   The name of the field
99	     * @param fieldEntity The element that should be set as value
100	     * @param criterion   Additional criterions to apply (optional)
101	     * @return The list of objects
102	     */
103	    @SuppressWarnings("unchecked")
104	    public List<E> findAllWhereFieldEquals(String fieldName, Object fieldEntity,
105	                                           Criterion... criterion) {
106	
107	        Class<?> fieldEntityType = null;
108	
109	        if (fieldEntity != null) {
110	            fieldEntityType = fieldEntity.getClass();
111	        }
112	
113	        final boolean isField = EntityUtil.isField(entityClass, fieldName, fieldEntityType, true);
114	
115	        if (!isField) {
116	            String errorMsg = String.format(
117	                "There is no field '%s' in the type '%s' that accepts instances of '%s'",
118	                fieldName,
119	                entityClass.getName(),
120	                fieldEntityType.getName()
121	            );
122	            throw new IllegalArgumentException(errorMsg);
123	        }
124	
125	        Criteria criteria = createDistinctRootEntityCriteria(criterion);
126	
127	        if (fieldEntity == null) {
128	            criteria.add(Restrictions.isNull(fieldName));
129	        } else {
130	            criteria.add(Restrictions.eq(fieldName, fieldEntity));
131	        }
132	        criteria.setCacheable(this.useQueryCache);
133	
134	        return (List<E>) criteria.list();
135	    }
136	
137	    /**
138	     * Returns a list of entity objects that have a collection named
139	     * <code>fieldName</code>, which contains the passed
140	     * <code>subElement</code>.
141	     * <p>
142	     * The can e.g. be used to return all applications that contain a certain layer.
143	     *
144	     * @param fieldName  The name of the collection field
145	     * @param subElement The element that should be contained in the collection
146	     * @param criterion  Additional criterions to apply (optional)
147	     * @return The list of objects
148	     */
149	    @SuppressWarnings("unchecked")
150	    public List<E> findAllWithCollectionContaining(String fieldName, PersistentObject subElement,
151	                                                   Criterion... criterion) {
152	        final Class<? extends PersistentObject> subElementType = subElement.getClass();
153	
154	        final boolean isCollectionField = EntityUtil.isCollectionField(entityClass, fieldName, subElementType, true);
155	
156	        if (!isCollectionField) {
157	            String errorMsg = String.format(
158	                "There is no collection field '%s' with element type '%s' in the type '%s'",
159	                fieldName,
160	                subElementType.getName(),
161	                entityClass.getName()
162	            );
163	            throw new IllegalArgumentException(errorMsg);
164	        }
165	
166	        Criteria criteria = createDistinctRootEntityCriteria(criterion);
167	        criteria.createAlias(fieldName, "sub");
168	        criteria.add(Restrictions.eq("sub.id", subElement.getId()));
169	        return (List<E>) criteria.list();
170	    }
