172	    /**
173	     * Return a proxy of the object (without hitting the database). This should
174	     * only be used if it is assumed that the object really exists and where
175	     * non-existence would be an actual error.
176	     *
177	     * @param id
178	     * @return
179	     * @see http://www.mkyong.com/hibernate/different-between-session-get-and-session-load/
180	     */
181	    public E loadById(ID id) {
182	        logger.trace("Loading " + entityClass.getSimpleName() + " with ID " + id);
183	        return getSession().load(entityClass, id);
184	    }
