186	    /**
187	     * Returns all Entities by calling findByCriteria(), i.e. without arguments.
188	     *
189	     * @return All entities
190	     * @see GenericHibernateDao#findByCriteria(Criterion...)
191	     */
192	    public List<E> findAll() throws HibernateException {
193	        logger.trace("Finding all instances of " + entityClass.getSimpleName());
194	        return findByCriteria();
195	    }
