197	    /**
198	     * Saves or updates the passed entity.
199	     *
200	     * @param e The entity to save or update in the database.
201	     */
202	    public void saveOrUpdate(E e) {
203	        final Integer id = e.getId();
204	        final boolean hasId = id != null;
205	        String createOrUpdatePrefix = hasId ? "Updating" : "Creating a new";
206	        String idSuffix = hasId ? " with ID " + id : "";
207	
208	        logger.trace(createOrUpdatePrefix + " instance of " + entityClass.getSimpleName()
209	            + idSuffix);
210	
211	        e.setModified(DateTime.now());
212	        getSession().saveOrUpdate(e);
213	    }
214	
215	    /**
216	     * Deletes the passed entity.
217	     *
218	     * @param e The entity to remove from the database.
219	     */
220	    public void delete(E e) {
221	        logger.trace("Deleting " + entityClass.getSimpleName() + " with ID " + e.getId());
222	        getSession().delete(e);
223	    }
