225	    /**
226	     * Unproxy the entity (and eagerly fetch properties).
227	     */
228	    @SuppressWarnings("unchecked")
229	    public E unproxy(E e) {
230	        if (e == null) {
231	            throw new NullPointerException("Entity passed for initialization is null");
232	        }
233	
234	        Hibernate.initialize(e);
235	
236	        if (e instanceof HibernateProxy) {
237	            e = (E) ((HibernateProxy) e).getHibernateLazyInitializer().getImplementation();
238	        }
239	
240	        return e;
241	    }
