243	    /**
244	     * Detach an entity from the hibernate session
245	     *
246	     * @param e
247	     */
248	    public void evict(E e) {
249	        logger.trace("Detaching " + entityClass.getSimpleName() + " with ID " + e.getId() + " from hibernate session");
250	        getSession().evict(e);
251	    }
