253	    /**
254	     * Gets the results, that match a variable number of passed criterions. Call
255	     * this method without arguments to find all entities.
256	     *
257	     * @param criterion A variable number of hibernate criterions
258	     * @return Entities matching the passed hibernate criterions
259	     */
260	    @SuppressWarnings("unchecked")
261	    public List<E> findByCriteria(Criterion... criterion) throws HibernateException {
262	        logger.trace("Finding instances of " + entityClass.getSimpleName()
263	            + " based on " + criterion.length + " criteria");
264	
265	        Criteria criteria = createDistinctRootEntityCriteria(criterion);
266	        return criteria.list();
267	    }
268	
269	    /**
270	     * Gets the results, that match a variable number of passed criterions, but return a
271	     * stripped version of the entities, where only the fieldNames in <code>restrictFieldNames</code>
272	     * have their actual values set.
273	     * <p>
274	     * You can call this with <code>restrictFieldNames</code> = <code>null</code> to get the full
275	     * entities back.
276	     * <p>
277	     * You can call this method without criterion arguments to find all entities (stripped down to
278	     * the <code>restrictFieldNames</code>).
279	     * <p>
280	     * If this is called as <code>findByCriteriaRestricted(null)</code> the return value equals the
281	     * return value of <code>findByCriteria()</code>.
282	     *
283	     * @param restrictFieldNames
284	     * @param criterion
285	     * @return
286	     * @throws HibernateException
287	     */
288	    @SuppressWarnings("unchecked")
289	    public List<E> findByCriteriaRestricted(List<String> restrictFieldNames, Criterion... criterion) throws HibernateException {
290	        logger.trace("Finding instances of " + entityClass.getSimpleName()
291	            + " based on " + criterion.length + " criteria");
292	
293	        Criteria criteria = createDistinctRootEntityCriteria(criterion);
294	
295	        if (restrictFieldNames != null) {
296	            ProjectionList projectionList = Projections.projectionList();
297	            for (String restrictFieldName : restrictFieldNames) {
298	                PropertyProjection pp = Projections.property(restrictFieldName);
299	                projectionList.add(pp, restrictFieldName);
300	            }
301	            criteria.setProjection(projectionList);
302	            criteria.setResultTransformer(
303	                Transformers.aliasToBean(entityClass)
304	            );
305	        }
306	
307	        return criteria.list();
308	    }
309	
310	    /**
311	     * Gets the unique result, that matches a variable number of passed
312	     * criterions.
313	     *
314	     * @param criterion A variable number of hibernate criterions
315	     * @return Entity matching the passed hibernate criterions
316	     * @throws HibernateException if there is more than one matching result
317	     */
318	    @SuppressWarnings("unchecked")
319	    public E findByUniqueCriteria(Criterion... criterion) throws HibernateException {
320	        logger.trace("Finding one unique " + entityClass.getSimpleName()
321	            + " based on " + criterion.length + " criteria");
322	
323	        Criteria criteria = createDistinctRootEntityCriteria(criterion);
324	        return (E) criteria.uniqueResult();
325	    }
326	
327	    /**
328	     * Gets the results, that match a variable number of passed criterions,
329	     * considering the paging- and sort-info at the same time.
330	     *
331	     * @param firstResult Starting index for the paging request.
332	     * @param maxResults  Max number of result size.
333	     * @param criterion   A variable number of hibernate criterions
334	     * @return
335	     */
336	    @SuppressWarnings("unchecked")
337	    public PagingResult<E> findByCriteriaWithSortingAndPaging(Integer firstResult,
338	                                                              Integer maxResults, List<Order> sorters, Criterion... criterion) throws HibernateException {
339	
340	        int nrOfSorters = sorters == null ? 0 : sorters.size();
341	
342	        logger.trace("Finding instances of " + entityClass.getSimpleName()
343	            + " based on " + criterion.length + " criteria"
344	            + " with " + nrOfSorters + " sorters");
345	
346	        Criteria criteria = createDistinctRootEntityCriteria(criterion);
347	
348	        // add paging info
349	        if (maxResults != null) {
350	            logger.trace("Limiting result set size to " + maxResults);
351	            criteria.setMaxResults(maxResults);
352	        }
353	        if (firstResult != null) {
354	            logger.trace("Setting the first result to be retrieved to "
355	                + firstResult);
356	            criteria.setFirstResult(firstResult);
357	        }
358	
359	        // add sort info
360	        if (sorters != null) {
361	            for (Order sortInfo : sorters) {
362	                criteria.addOrder(sortInfo);
363	            }
364	        }
365	
366	        return new PagingResult<E>(criteria.list(), getTotalCount(criterion));
367	    }
368	
369	    /**
370	     * This method returns a {@link Map} that maps {@link PersistentObject}s
371	     * to PermissionCollections for the passed {@link User}. I.e. the keySet
372	     * of the map is the collection of all {@link PersistentObject}s where the
373	     * user has at least one permission and the corresponding value contains
374	     * the {@link PermissionCollection} for the passed user on the entity.
375	     *
376	     * @param user
377	     * @return
378	     */
379	    @SuppressWarnings({"unchecked"})
380	    public Map<PersistentObject, PermissionCollection> findAllUserPermissionsOfUser(User user) {
381	
382	        Criteria criteria = getSession().createCriteria(PersistentObject.class);
383	
384	        // by only setting the alias, we will only get those entities where
385	        // there is at least one permission set...
386	        // it is hard (or even impossible in this scenario) to create a
387	        // restriction that filters for permissions of the given user only.
388	        // using HQL here is no option as the PersistentObject is
389	        // a MappedSuperclass (without table).
390	        // another efficient way would be a SQL query, but then the SQL
391	        // would be written in an explicit SQL dialect...
392	        criteria.createAlias("userPermissions", "up");
393	        criteria.setResultTransformer(Criteria.DISTINCT_ROOT_ENTITY);
394	
395	        List<PersistentObject> entitiesWithPermissions = criteria.list();
396	
397	        Map<PersistentObject, PermissionCollection> userPermissions = new HashMap<PersistentObject, PermissionCollection>();
398	
399	        // TODO find a better way than iterating over all entities of the system
400	        // that have at least one permission (for any user) (see comment above)
401	        for (PersistentObject entity : entitiesWithPermissions) {
402	            Map<User, PermissionCollection> entityUserPermissions = entity.getUserPermissions();
403	            if (entityUserPermissions.containsKey(user)) {
404	                userPermissions.put(entity, entityUserPermissions.get(user));
405	            }
406	        }
407	
408	        return userPermissions;
409	    }
410	
411	    /**
412	     * This method returns a {@link Map} that maps {@link PersistentObject}s
413	     * to PermissionCollections for the passed {@link UserGroup}. I.e. the keySet
414	     * of the map is the collection of all {@link PersistentObject}s where the
415	     * user group has at least one permission and the corresponding value contains
416	     * the {@link PermissionCollection} for the passed user group on the entity.
417	     *
418	     * @param userGroup
419	     * @return
420	     */
421	    @SuppressWarnings({"unchecked"})
422	    public Map<PersistentObject, PermissionCollection> findAllUserGroupPermissionsOfUserGroup(UserGroup userGroup) {
423	
424	        Criteria criteria = getSession().createCriteria(PersistentObject.class);
425	
426	        // by only setting the alias, we will only get those entities where
427	        // there is at least one permission set...
428	        // it is hard (or even impossible in this scenario) to create a
429	        // restriction that filters for permissions of the given user group only.
430	        // using HQL here is no option as the PersistentObject is
431	        // a MappedSuperclass (without table).
432	        // another efficient way would be a SQL query, but then the SQL
433	        // would be written in an explicit SQL dialect...
434	        criteria.createAlias("groupPermissions", "gp");
435	        criteria.setResultTransformer(Criteria.DISTINCT_ROOT_ENTITY);
436	
437	        List<PersistentObject> entitiesWithPermissions = criteria.list();
438	
439	        Map<PersistentObject, PermissionCollection> userGroupPermissions = new HashMap<PersistentObject, PermissionCollection>();
440	
441	        // TODO find a better way than iterating over all entities of the system
442	        // that have at least one permission (for any user) (see comment above)
443	        for (PersistentObject entity : entitiesWithPermissions) {
444	            Map<UserGroup, PermissionCollection> entityUserGroupPermissions = entity.getGroupPermissions();
445	            if (entityUserGroupPermissions.containsKey(userGroup)) {
446	                userGroupPermissions.put(entity, entityUserGroupPermissions.get(userGroup));
447	            }
448	        }
449	
450	        return userGroupPermissions;
451	    }
452	
453	    /**
454	     * Helper method: Creates a criteria for the {@link #entityClass} of this dao.
455	     * The query results will be handled with a
456	     * {@link DistinctRootEntityResultTransformer}. The criteria will contain
457	     * all passed criterions.
458	     *
459	     * @return
460	     */
461	    protected Criteria createDistinctRootEntityCriteria(Criterion... criterion) {
462	        Criteria criteria = getSession().createCriteria(entityClass);
463	        addCriterionsToCriteria(criteria, criterion);
464	        criteria.setResultTransformer(Criteria.DISTINCT_ROOT_ENTITY);
465	        criteria.setCacheable(this.useQueryCache);
466	        return criteria;
467	    }
468	
469	    /**
470	     * Returns the total count of db entries for the current type.
471	     *
472	     * @param criterion
473	     * @return
474	     */
475	    public Number getTotalCount(Criterion... criterion) throws HibernateException {
476	        Criteria criteria = getSession().createCriteria(entityClass);
477	        addCriterionsToCriteria(criteria, criterion);
478	        criteria.setProjection(Projections.rowCount());
479	        return (Long) criteria.uniqueResult();
480	    }
481	
482	    /**
483	     * Helper method: Adds all criterions to the criteria (if not null).
484	     *
485	     * @param criteria
486	     * @param criterion
487	     */
488	    private void addCriterionsToCriteria(Criteria criteria, Criterion... criterion) {
489	        if (criteria != null) {
490	            for (Criterion c : criterion) {
491	                if (c != null) {
492	                    criteria.add(c);
493	                }
494	            }
495	        }
496	    }
497	
498	    /**
499	     * @return the entityClass
500	     */
501	    public Class<E> getEntityClass() {
502	        return entityClass;
503	    }
504	
505	}
