 * @author Kai Volland
 * @author terrestris GmbH & Co. KG
 */
@Repository("interceptorRuleDao")
public class InterceptorRuleDao<E extends InterceptorRule>
    extends GenericHibernateDao<E, Integer> {

    /**
     * Public default constructor for this DAO.
     */
    @SuppressWarnings("unchecked")
    public InterceptorRuleDao() {
        super((Class<E>) InterceptorRule.class);
    }

    /**
     * Constructor that has to be called by subclasses.
     *
     * @param clazz
     */
    protected InterceptorRuleDao(Class<E> clazz) {
        super(clazz);
    }

    /**
     * @param service
     * @param event
     * @return
     */
    @SuppressWarnings("unchecked")
    public List<E> findAllRulesForServiceAndEvent(String service, String event) {

        final OgcEnum.ServiceType serviceType = OgcEnum.ServiceType.fromString(service);
        final HttpEnum.EventType eventType = HttpEnum.EventType.fromString(event);

        QueryRestriction<E> eqService =
            (root, query, cb) -> cb.equal(root.get("service"), serviceType);
        QueryRestriction<E> eqEvent =
            (root, query, cb) -> cb.equal(root.get("event"), eventType);

        // order descending by endPoint and operation, so the more specific
        // rules will be listed first (this could make the following evaluation
        // easier)
        List<SortOrder> sorters = Arrays.asList(
            SortOrder.desc("endPoint"),
            SortOrder.desc("operation")
        );

        return findByCriteriaSorted(sorters, eqService, eqEvent);
    }

}
