package de.terrestris.shoguncore.dao;

import de.terrestris.shoguncore.model.Application;
import de.terrestris.shoguncore.model.PersistentObject;
import de.terrestris.shoguncore.model.User;
import de.terrestris.shoguncore.model.UserGroup;
import de.terrestris.shoguncore.model.interceptor.InterceptorRule;
import de.terrestris.shoguncore.model.security.Permission;
import de.terrestris.shoguncore.model.security.PermissionCollection;
import de.terrestris.shoguncore.util.enumeration.HttpEnum;
import de.terrestris.shoguncore.util.enumeration.InterceptorEnum;
import de.terrestris.shoguncore.util.enumeration.OgcEnum;
import org.junit.jupiter.api.Test;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.test.annotation.Rollback;
import org.springframework.test.context.ContextConfiguration;
import org.springframework.test.context.junit.jupiter.SpringExtension;
import org.junit.jupiter.api.extension.ExtendWith;
import org.springframework.transaction.annotation.Transactional;

import java.util.Arrays;
import java.util.EnumSet;
import java.util.List;
import java.util.Map;

import static org.junit.jupiter.api.Assertions.*;

/**
 * SCRATCH verification of the rewritten query paths (to be deleted).
 */
@ExtendWith(SpringExtension.class)
@ContextConfiguration(locations = {"classpath*:META-INF/spring/test-context-dao.xml"})
@Transactional
@Rollback(true)
public class ScratchVerificationTest {

    @Autowired
    AppTestDao appDao;

    @Autowired
    UserDao<User> userDao;

    @Autowired
    UserGroupDao<UserGroup> groupDao;

    @Autowired
    InterceptorRuleDao<InterceptorRule> ruleDao;

    @Test
    public void restricted_onlyListedFieldsAreSet() {
        Application a = new Application("scratch-restricted", "desc-r");
        appDao.saveOrUpdate(a);

        QueryRestriction<Application> byName = (root, q, cb) -> cb.equal(root.get("name"), "scratch-restricted");
        List<Application> got = appDao.findByCriteriaRestricted(Arrays.asList("name"), byName);
        assertEquals(1, got.size());
        assertEquals("scratch-restricted", got.get(0).getName());
        assertNull(got.get(0).getDescription());
        assertNull(got.get(0).getId());

        List<Application> full = appDao.findByCriteriaRestricted(null, byName);
        assertEquals(1, full.size());
        assertEquals("desc-r", full.get(0).getDescription());
        assertNotNull(full.get(0).getId());
    }

    @Test
    public void restricted_withoutRestrictionReturnsAll() {
        appDao.saveOrUpdate(new Application("scratch-all-1", "x"));
        appDao.saveOrUpdate(new Application("scratch-all-2", "y"));
        List<Application> got = appDao.findByCriteriaRestricted(Arrays.asList("name", "description"));
        assertTrue(got.size() >= 2);
        assertTrue(got.stream().anyMatch(app -> "scratch-all-1".equals(app.getName()) && "x".equals(app.getDescription())));
    }

    @Test
    public void sortedAndPaged_orOfFieldValues() {
        appDao.saveOrUpdate(new Application("scratch-or-1", "d"));
        appDao.saveOrUpdate(new Application("scratch-or-2", "d"));
        appDao.saveOrUpdate(new Application("scratch-or-3", "d"));
        QueryRestriction<Application> or = (root, q, cb) -> cb.or(
            cb.equal(root.get("name"), "scratch-or-1"),
            cb.equal(root.get("name"), "scratch-or-3"));
        List<Application> got = appDao.findByCriteriaRestricted(Arrays.asList("name"), or);
        assertEquals(2, got.size());
        assertEquals(2, appDao.getTotalCount(or).intValue());
        PagingResultHolder r = new PagingResultHolder(appDao.findByCriteriaWithSortingAndPaging(
            0, 1, Arrays.asList(SortOrder.desc("name")), or));
        assertEquals(1, r.size);
        assertEquals("scratch-or-3", r.first);
        assertEquals(2L, r.total);
    }

    @Test
    public void userPermissions_ofUser() {
        User u = new User("First", "Last", "scratch-perm-user");
        userDao.saveOrUpdate(u);
        Application a = new Application("scratch-perm-app", "d");
        PermissionCollection pc = new PermissionCollection(EnumSet.of(Permission.READ));
        a.getUserPermissions().put(u, pc);
        appDao.saveOrUpdate(a);

        Map<PersistentObject, PermissionCollection> m = appDao.findAllUserPermissionsOfUser(u);
        assertTrue(m.containsKey(a), "user permissions contain the app");
        assertEquals(pc.getPermissions(), m.get(a).getPermissions());
    }

    @Test
    public void groupPermissions_ofGroup() {
        UserGroup g = new UserGroup();
        g.setName("scratch-group");
        groupDao.saveOrUpdate(g);
        Application a = new Application("scratch-group-app", "d");
        PermissionCollection pc = new PermissionCollection(EnumSet.of(Permission.CREATE));
        a.getGroupPermissions().put(g, pc);
        appDao.saveOrUpdate(a);

        Map<PersistentObject, PermissionCollection> m = appDao.findAllUserGroupPermissionsOfUserGroup(g);
        assertTrue(m.containsKey(a), "group permissions contain the app");
    }

    @Test
    public void userDao_findByAccountNameAndEmail() {
        User u = new User("F", "L", "scratch-acc");
        u.setEmail("scratch@example.org");
        userDao.saveOrUpdate(u);
        assertNotNull(userDao.findByAccountName("scratch-acc"));
        assertNull(userDao.findByAccountName("does-not-exist"));
        assertNotNull(userDao.findByEmail("scratch@example.org"));
    }

    @Test
    public void interceptorRules_forServiceAndEvent() {
        ruleDao.saveOrUpdate(new InterceptorRule(HttpEnum.EventType.REQUEST, InterceptorEnum.RuleType.ALLOW,
            OgcEnum.ServiceType.WMS, OgcEnum.OperationType.GET_MAP, "b-endpoint"));
        ruleDao.saveOrUpdate(new InterceptorRule(HttpEnum.EventType.REQUEST, InterceptorEnum.RuleType.DENY,
            OgcEnum.ServiceType.WMS, OgcEnum.OperationType.GET_MAP, "a-endpoint"));
        ruleDao.saveOrUpdate(new InterceptorRule(HttpEnum.EventType.RESPONSE, InterceptorEnum.RuleType.DENY,
            OgcEnum.ServiceType.WMS, OgcEnum.OperationType.GET_MAP, "c-endpoint"));
        List<InterceptorRule> rules = ruleDao.findAllRulesForServiceAndEvent("WMS", "REQUEST");
        assertEquals(2, rules.size());
        assertEquals("b-endpoint", rules.get(0).getEndPoint());
        assertEquals("a-endpoint", rules.get(1).getEndPoint());
    }

    /** tiny holder to keep the assertions readable */
    static class PagingResultHolder {
        final int size;
        final String first;
        final long total;

        PagingResultHolder(de.terrestris.shoguncore.paging.PagingResult<Application> r) {
            this.size = r.getResultList().size();
            this.first = r.getResultList().get(0).getName();
            this.total = r.getTotalCount().longValue();
        }
    }
}

