import org.junit.jupiter.api.extension.ExtendWith;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.test.annotation.Rollback;
import org.springframework.test.context.ContextConfiguration;
import org.springframework.test.context.junit.jupiter.SpringExtension;
import org.springframework.transaction.annotation.Transactional;

import java.util.Arrays;
import java.util.EnumSet;
import java.util.List;
import java.util.Map;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertNotNull;
import static org.junit.jupiter.api.Assertions.assertNull;
import static org.junit.jupiter.api.Assertions.assertTrue;

/**
 * Tests the JPA Criteria based query methods of the {@link GenericHibernateDao}
 * (and of the DAOs using them) against the database.
 */
@ExtendWith(SpringExtension.class)
@ContextConfiguration(locations = {"classpath*:META-INF/spring/test-context-dao.xml"})
@Transactional
@Rollback(true)
public class GenericHibernateDaoQueryTest {

    @Autowired
    private AppTestDao appDao;

    @Autowired
    private UserDao<User> userDao;

    @Autowired
    private UserGroupDao<UserGroup> userGroupDao;

    @Autowired
    private PermissionCollectionDao<PermissionCollection> permissionCollectionDao;

    @Autowired
    private InterceptorRuleDao<InterceptorRule> interceptorRuleDao;

    /**
     * Tests whether findByCriteriaRestricted() only sets the listed fields.
     */
    @Test
    public void findByCriteriaRestricted_onlySetsRestrictedFields() {
        appDao.saveOrUpdate(new Application("restricted app", "restricted description"));

        QueryRestriction<Application> byName =
            (root, query, cb) -> cb.equal(root.get("name"), "restricted app");

        List<Application> restricted = appDao.findByCriteriaRestricted(Arrays.asList("name"), byName);
        assertEquals(1, restricted.size());
        assertEquals("restricted app", restricted.get(0).getName());
        assertNull(restricted.get(0).getDescription());
        assertNull(restricted.get(0).getId());

        List<Application> full = appDao.findByCriteriaRestricted(null, byName);
        assertEquals(1, full.size());
        assertEquals("restricted description", full.get(0).getDescription());
        assertNotNull(full.get(0).getId());
    }

    /**
     * Tests whether findByCriteriaRestricted() without restrictions returns all
     * entities, only with the listed fields set.
     */
    @Test
    public void findByCriteriaRestricted_withoutRestrictionsReturnsAllEntities() {
        appDao.saveOrUpdate(new Application("all app 1", "x"));
        appDao.saveOrUpdate(new Application("all app 2", "y"));

        List<Application> got = appDao.findByCriteriaRestricted(Arrays.asList("name", "description"));

        assertTrue(got.stream().anyMatch(app -> "all app 1".equals(app.getName()) && "x".equals(app.getDescription())));
        assertTrue(got.stream().anyMatch(app -> "all app 2".equals(app.getName()) && "y".equals(app.getDescription())));
    }

    /**
     * Tests whether sorting, paging and counting work together with restrictions.
     */
    @Test
    public void findByCriteriaWithSortingAndPaging_worksWithRestrictionsAndTotalCount() {
        appDao.saveOrUpdate(new Application("sorted app 1", "d"));
        appDao.saveOrUpdate(new Application("sorted app 2", "d"));
        appDao.saveOrUpdate(new Application("sorted app 3", "d"));

        QueryRestriction<Application> oneOrThree = (root, query, cb) -> cb.or(
            cb.equal(root.get("name"), "sorted app 1"),
            cb.equal(root.get("name"), "sorted app 3"));

        assertEquals(2, appDao.getTotalCount(oneOrThree).intValue());

        PagingResult<Application> page = appDao.findByCriteriaWithSortingAndPaging(
            0, 1, Arrays.asList(SortOrder.desc("name")), oneOrThree);

        assertEquals(1, page.getResultList().size());
        assertEquals("sorted app 3", page.getResultList().get(0).getName());
        assertEquals(2L, page.getTotalCount().longValue());
    }

    /**
     * Tests whether findAllUserPermissionsOfUser() returns the entities the user
     * has permissions on.
     */
    @Test
    public void findAllUserPermissionsOfUser_returnsEntitiesWithPermissionsOfUser() {
        User user = new User("First", "Last", "permission user");
        userDao.saveOrUpdate(user);

        Application app = new Application("permission app", "d");
        PermissionCollection permissions = new PermissionCollection(EnumSet.of(Permission.READ));
        permissionCollectionDao.saveOrUpdate(permissions);
        app.getUserPermissions().put(user, permissions);
        appDao.saveOrUpdate(app);

        Map<PersistentObject, PermissionCollection> result = appDao.findAllUserPermissionsOfUser(user);

        assertTrue(result.containsKey(app));
        assertEquals(permissions.getPermissions(), result.get(app).getPermissions());
    }

    /**
     * Tests whether findAllUserGroupPermissionsOfUserGroup() returns the entities
     * the user group has permissions on.
     */
    @Test
    public void findAllUserGroupPermissionsOfUserGroup_returnsEntitiesWithPermissionsOfGroup() {
        UserGroup group = new UserGroup();
        group.setName("permission group");
        userGroupDao.saveOrUpdate(group);

        Application app = new Application("group permission app", "d");
        PermissionCollection permissions = new PermissionCollection(EnumSet.of(Permission.CREATE));
        permissionCollectionDao.saveOrUpdate(permissions);
        app.getGroupPermissions().put(group, permissions);
        appDao.saveOrUpdate(app);

        Map<PersistentObject, PermissionCollection> result = appDao.findAllUserGroupPermissionsOfUserGroup(group);

        assertTrue(result.containsKey(app));
    }

    /**
     * Tests whether the user DAO finds users by account name and email.
     */
    @Test
    public void userDao_findsUsersByAccountNameAndEmail() {
        User user = new User("First", "Last", "lookup account");
        user.setEmail("lookup@example.org");
        userDao.saveOrUpdate(user);

        assertNotNull(userDao.findByAccountName("lookup account"));
        assertNull(userDao.findByAccountName("unknown account"));
        assertNotNull(userDao.findByEmail("lookup@example.org"));
    }

    /**
     * Tests whether the interceptor rules are filtered by service and event and
     * ordered by endpoint (descending).
     */
    @Test
    public void findAllRulesForServiceAndEvent_filtersAndSortsRules() {
        interceptorRuleDao.saveOrUpdate(new InterceptorRule(HttpEnum.EventType.REQUEST,
            InterceptorEnum.RuleType.ALLOW, OgcEnum.ServiceType.WMS, OgcEnum.OperationType.GET_MAP, "b-endpoint"));
        interceptorRuleDao.saveOrUpdate(new InterceptorRule(HttpEnum.EventType.REQUEST,
            InterceptorEnum.RuleType.DENY, OgcEnum.ServiceType.WMS, OgcEnum.OperationType.GET_MAP, "a-endpoint"));
        interceptorRuleDao.saveOrUpdate(new InterceptorRule(HttpEnum.EventType.RESPONSE,
            InterceptorEnum.RuleType.DENY, OgcEnum.ServiceType.WMS, OgcEnum.OperationType.GET_MAP, "c-endpoint"));

        List<InterceptorRule> rules = interceptorRuleDao.findAllRulesForServiceAndEvent("WMS", "REQUEST");

        assertEquals(2, rules.size());
        assertEquals("b-endpoint", rules.get(0).getEndPoint());
        assertEquals("a-endpoint", rules.get(1).getEndPoint());
    }

}

