package de.terrestris.shoguncore.dao;

import de.terrestris.shoguncore.model.PersistentObject;
import de.terrestris.shoguncore.model.Plugin;
import de.terrestris.shoguncore.model.layer.appearance.LayerAppearance;
import de.terrestris.shoguncore.model.map.MapControl;
import de.terrestris.shoguncore.model.module.Button;
import de.terrestris.shoguncore.model.module.Module;
import de.terrestris.shoguncore.model.wps.WpsProcessExecute;
import org.apache.commons.lang3.RandomStringUtils;
import org.junit.jupiter.api.extension.ExtendWith;
import org.junit.jupiter.api.Test;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.test.annotation.Rollback;
import org.springframework.test.context.ContextConfiguration;
import org.springframework.test.context.junit.jupiter.SpringExtension;
import org.springframework.transaction.annotation.Transactional;

import java.util.HashMap;
import java.util.Map;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertNotNull;

/**
 * Tests that entities with long text columns and map-valued element collections
 * are stored and loaded again by Hibernate.
 */
@ExtendWith(SpringExtension.class)
@ContextConfiguration(locations = {"classpath*:META-INF/spring/test-context-dao.xml"})
@Transactional
@Rollback(true)
public class EntityMappingRoundTripTest {

    @Autowired
    private PluginDao<Plugin> pluginDao;

    @Autowired
    private ModuleDao<Module> moduleDao;

    @Autowired
    private LayerAppearanceDao<LayerAppearance> layerAppearanceDao;

    @Autowired
    private WpsProcessExecuteDao<WpsProcessExecute> wpsProcessExecuteDao;

    @Autowired
    private MapControlDao<MapControl> mapControlDao;

    /**
     * Tests whether a long text (e.g. JavaScript source code) survives the round trip.
     */
    @Test
    public void plugin_sourceCodeSurvivesDatabaseRoundTrip() {
        String sourceCode = RandomStringUtils.random(5000, true, true);
        Plugin plugin = new Plugin();
        plugin.setName("round trip plugin");
        plugin.setClassName("de.terrestris.roundtrip.Plugin");
        plugin.setSourceCode(sourceCode);
        plugin.setStyleSheet("body { color: red; }");

        Plugin reloaded = reload(pluginDao, plugin);

        assertNotNull(reloaded);
        assertEquals(sourceCode, reloaded.getSourceCode());
        assertEquals("body { color: red; }", reloaded.getStyleSheet());
    }

    /**
     * Tests whether the properties map of a module survives the round trip.
     */
    @Test
    public void module_propertiesSurviveDatabaseRoundTrip() {
        Button button = new Button();
        button.setName("round trip button");
        Map<String, Object> properties = new HashMap<>();
        properties.put("tooltip", "a tooltip");
        button.setProperties(properties);

        Module reloaded = reload(moduleDao, button);

        assertNotNull(reloaded);
        assertEquals("a tooltip", reloaded.getProperties().get("tooltip"));
    }

    /**
     * Tests whether the properties map of a layer appearance survives the round trip.
     */
    @Test
    public void layerAppearance_propertiesSurviveDatabaseRoundTrip() {
        LayerAppearance appearance = new LayerAppearance();
        appearance.setName("round trip appearance");
        Map<String, Object> properties = new HashMap<>();
        properties.put("fill", "#ff0000");
        appearance.setProperties(properties);

        LayerAppearance reloaded = reload(layerAppearanceDao, appearance);

        assertNotNull(reloaded);
