import re
CMT='''    // eager join fetches of these cyclic associations (users, groups, roles and their
    // permissions) make Hibernate 6 generate an enormous join over and over again,
    // so they are loaded by a subselect instead
'''
def edit(f, old, new):
    s=open(f).read()
    assert s.count(old)==1,(f,s.count(old))
    s=s.replace(old,new)
    open(f,'w').write(s)
edit('PersistentObject.java','''    @ManyToMany
    @JoinTable(
        name = "USERPERMISSIONS",
        joinColumns = @JoinColumn(name = "ENTITY_ID"))
    @JsonIgnore
    @Cache(usage = CacheConcurrencyStrategy.READ_WRITE)
    @Fetch(FetchMode.JOIN)
    private Map<User, PermissionCollection> userPermissions''','''''' + CMT + '''    @ManyToMany(fetch = FetchType.EAGER)
    @JoinTable(
        name = "USERPERMISSIONS",
        joinColumns = @JoinColumn(name = "ENTITY_ID"))
    @JsonIgnore
    @Cache(usage = CacheConcurrencyStrategy.READ_WRITE)
    @Fetch(FetchMode.SUBSELECT)
    private Map<User, PermissionCollection> userPermissions''')
edit('PersistentObject.java','''    @ManyToMany
    @JoinTable(
        name = "GROUPPERMISSIONS",
        joinColumns = @JoinColumn(name = "ENTITY_ID"))
    @JsonIgnore
    @Cache(usage = CacheConcurrencyStrategy.READ_WRITE)
    @Fetch(FetchMode.JOIN)
    private Map<UserGroup, PermissionCollection> groupPermissions''','''    @ManyToMany(fetch = FetchType.EAGER)
    @JoinTable(
        name = "GROUPPERMISSIONS",
        joinColumns = @JoinColumn(name = "ENTITY_ID"))
    @JsonIgnore
    @Cache(usage = CacheConcurrencyStrategy.READ_WRITE)
    @Fetch(FetchMode.SUBSELECT)
    private Map<UserGroup, PermissionCollection> groupPermissions''')
edit('UserGroup.java','''    @ManyToMany
    @Cache(usage = CacheConcurrencyStrategy.READ_WRITE)
    @Fetch(FetchMode.JOIN)
    @JoinTable(
        name = "user_usergroup",
        joinColumns = {@JoinColumn(name = "USERGROUP_ID")},
        inverseJoinColumns = {@JoinColumn(name = "USER_ID")}
    )
    private Set<User> members''','''    // eager join fetches of this cyclic association (users and groups reference each other)
    // make Hibernate 6 generate an enormous join, so the members are loaded by a subselect
    @ManyToMany(fetch = FetchType.EAGER)
    @Cache(usage = CacheConcurrencyStrategy.READ_WRITE)
    @Fetch(FetchMode.SUBSELECT)
    @JoinTable(
        name = "user_usergroup",
        joinColumns = {@JoinColumn(name = "USERGROUP_ID")},
        inverseJoinColumns = {@JoinColumn(name = "USER_ID")}
    )
    private Set<User> members''')
print('ok')
